package com.meta.wearable.dat.externalsampleapps.cameraaccess.vision

import android.graphics.Bitmap
import android.util.Base64
import android.util.Log
import com.meta.wearable.dat.externalsampleapps.cameraaccess.gemini.GeminiConfig
import java.io.ByteArrayOutputStream
import java.util.concurrent.TimeUnit
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONObject

class VisionToolClient(
    private val client: OkHttpClient =
        OkHttpClient.Builder()
            .connectTimeout(10, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(60, TimeUnit.SECONDS)
            .callTimeout(75, TimeUnit.SECONDS)
            .build(),
) {
    companion object {
        private const val TAG = "VisionToolClient"
        private val JSON_MEDIA_TYPE = "application/json".toMediaType()
    }

    suspend fun locateObject(
        bitmap: Bitmap,
        query: String,
        includeSegmentation: Boolean,
    ): ObjectDetectionResult =
        withContext(Dispatchers.IO) {
            val startedAt = System.currentTimeMillis()
            val baseUrl = GeminiConfig.visionToolBaseUrl.trim()
            check(baseUrl.isNotEmpty()) {
                "Vision tool URL is not configured. Add it in Settings > Vision Tool."
            }

            Log.d(
                TAG,
                "locateObject start query='$query' includeSegmentation=$includeSegmentation frame=${bitmap.width}x${bitmap.height} url=$baseUrl",
            )

            val payload =
                JSONObject()
                    .put("query", query)
                    .put("includeSegmentation", includeSegmentation)
                    .put("imageBase64", bitmap.toJpegBase64())
                    .put("frameWidth", bitmap.width)
                    .put("frameHeight", bitmap.height)

            val request =
                Request.Builder()
                    .url("${baseUrl.removeSuffix("/")}/locate-object")
                    .post(payload.toString().toRequestBody(JSON_MEDIA_TYPE))
                    .apply {
                        val token = <REDACTED>
                        if (token.isNotEmpty()) {
                            header("Authorization", "Bearer $token")
                        }
                    }
                    .build()

            client.newCall(request).execute().use { response ->
                val body = response.body?.string().orEmpty()
                val elapsed = System.currentTimeMillis() - startedAt
                Log.d(
                    TAG,
                    "locateObject response query='$query' code=${response.code} elapsedMs=$elapsed bodyPreview='${body.take(240)}'",
                )
                check(response.isSuccessful) {
                    "Vision tool failed (${response.code}): ${body.take(300)}"
                }
                check(body.isNotBlank()) { "Vision tool returned an empty response." }
                ObjectDetectionResult.fromJSON(JSONObject(body)).also { result ->
                    Log.d(
                        TAG,
                        "locateObject parsed query='$query' found=${result.found} label='${result.label}' confidence=${result.confidence}",
                    )
                }
            }
        }

    suspend fun guideStep(
        task: String,
        stepIndex: Int,
        observedLabel: String?,
        objectFound: Boolean,
        sessionId: String? = null,
    ): JSONObject =
        withContext(Dispatchers.IO) {
            val startedAt = System.currentTimeMillis()
            val baseUrl = GeminiConfig.visionToolBaseUrl.trim()
            check(baseUrl.isNotEmpty()) {
                "Vision tool URL is not configured. Add it in Settings > Vision Tool."
            }

            Log.d(
                TAG,
                "guideStep start task='$task' stepIndex=$stepIndex observedLabel='${observedLabel ?: ""}' objectFound=$objectFound url=$baseUrl",
            )

            val payload =
                JSONObject()
                    .put("task", task)
                    .put("stepIndex", stepIndex)
                    .put("observedLabel", observedLabel)
                    .put("objectFound", objectFound)
                    .put("sessionId", sessionId)

            val request =
                Request.Builder()
                    .url("${baseUrl.removeSuffix("/")}/guide-step")
                    .post(payload.toString().toRequestBody(JSON_MEDIA_TYPE))
                    .apply {
                        val token = <REDACTED>
                        if (token.isNotEmpty()) {
                            header("Authorization", "Bearer $token")
                        }
                    }
                    .build()

            client.newCall(request).execute().use { response ->
                val body = response.body?.string().orEmpty()
                val elapsed = System.currentTimeMillis() - startedAt
                Log.d(
                    TAG,
                    "guideStep response stepIndex=$stepIndex code=${response.code} elapsedMs=$elapsed bodyPreview='${body.take(240)}'",
                )
                check(response.isSuccessful) {
                    "Guide step failed (${response.code}): ${body.take(300)}"
                }
                check(body.isNotBlank()) { "Guide step returned an empty response." }
                JSONObject(body)
            }
        }

    suspend fun trackTarget(
        bitmap: Bitmap,
        query: String,
        previousBbox: JSONObject?,
    ): ObjectDetectionResult =
        withContext(Dispatchers.IO) {
            val startedAt = System.currentTimeMillis()
            val baseUrl = GeminiConfig.visionToolBaseUrl.trim()
            check(baseUrl.isNotEmpty()) {
                "Vision tool URL is not configured. Add it in Settings > Vision Tool."
            }

            Log.d(
                TAG,
                "trackTarget start query='$query' frame=${bitmap.width}x${bitmap.height} url=$baseUrl",
            )

            val payload =
                JSONObject()
                    .put("query", query)
                    .put("imageBase64", bitmap.toJpegBase64())
                    .put("frameWidth", bitmap.width)
                    .put("frameHeight", bitmap.height)
                    .put("previousBbox", previousBbox)

            val request =
                Request.Builder()
                    .url("${baseUrl.removeSuffix("/")}/track-target")
                    .post(payload.toString().toRequestBody(JSON_MEDIA_TYPE))
                    .apply {
                        val token = <REDACTED>
                        if (token.isNotEmpty()) {
                            header("Authorization", "Bearer $token")
                        }
                    }
                    .build()

            client.newCall(request).execute().use { response ->
                val body = response.body?.string().orEmpty()
                val elapsed = System.currentTimeMillis() - startedAt
                Log.d(
                    TAG,
                    "trackTarget response query='$query' code=${response.code} elapsedMs=$elapsed bodyPreview='${body.take(240)}'",
                )
                check(response.isSuccessful) {
                    "Track target failed (${response.code}): ${body.take(300)}"
                }
                check(body.isNotBlank()) { "Track target returned an empty response." }
                ObjectDetectionResult.fromJSON(JSONObject(body))
            }
        }

    suspend fun startGuidance(
        task: String?,
        sessionId: String? = null,
    ): JSONObject = postJson(
        endpoint = "/start-guidance",
        payload =
            JSONObject()
                .put("task", task)
                .put("sessionId", sessionId),
        logName = "startGuidance",
    )

    suspend fun advanceStep(sessionId: String?): JSONObject = postJson(
        endpoint = "/advance-step",
        payload = JSONObject().put("sessionId", sessionId),
        logName = "advanceStep",
    )

    private suspend fun postJson(
        endpoint: String,
        payload: JSONObject,
        logName: String,
    ): JSONObject =
        withContext(Dispatchers.IO) {
            val startedAt = System.currentTimeMillis()
            val baseUrl = GeminiConfig.visionToolBaseUrl.trim()
            check(baseUrl.isNotEmpty()) {
                "Vision tool URL is not configured. Add it in Settings > Vision Tool."
            }
            Log.d(TAG, "$logName start endpoint=$endpoint payload='${payload.toString().take(240)}'")
            val request =
                Request.Builder()
                    .url("${baseUrl.removeSuffix("/")}$endpoint")
                    .post(payload.toString().toRequestBody(JSON_MEDIA_TYPE))
                    .apply {
                        val token = <REDACTED>
                        if (token.isNotEmpty()) {
                            header("Authorization", "Bearer $token")
                        }
                    }
                    .build()

            client.newCall(request).execute().use { response ->
                val body = response.body?.string().orEmpty()
                val elapsed = System.currentTimeMillis() - startedAt
                Log.d(
                    TAG,
                    "$logName response endpoint=$endpoint code=${response.code} elapsedMs=$elapsed bodyPreview='${body.take(240)}'",
                )
                check(response.isSuccessful) {
                    "$logName failed (${response.code}): ${body.take(300)}"
                }
                check(body.isNotBlank()) { "$logName returned an empty response." }
                JSONObject(body)
            }
        }

    suspend fun inspectObject(
        query: String?,
        image: Bitmap?,
    ): JSONObject =
        withContext(Dispatchers.IO) {
            val payload =
                JSONObject()
                    .put("query", query)
                    .put("imageBase64", image?.toJpegBase64())
            postJson("/inspect-object", payload, "inspectObject")
        }
}

private fun Bitmap.toJpegBase64(): String {
    val output = ByteArrayOutputStream()
    compress(Bitmap.CompressFormat.JPEG, 85, output)
    return Base64.encodeToString(output.toByteArray(), Base64.NO_WRAP)
}

package com.meta.wearable.dat.externalsampleapps.cameraaccess.visionagent

import android.graphics.Bitmap
import android.util.Base64
import android.util.Log
import com.meta.wearable.dat.externalsampleapps.cameraaccess.gemini.GeminiConfig
import java.io.ByteArrayOutputStream
import java.io.IOException
import java.util.concurrent.TimeUnit
import org.json.JSONArray
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import okio.ByteString
import org.json.JSONObject

data class VisionAgentBootstrapPayload(
    val sessionId: String,
    val provider: String,
    val callId: String?,
    val callType: String?,
    val agentSessionId: String?,
    val streamApiKey: <REDACTED>
    val streamUserId: String?,
    val streamUserToken: <REDACTED>
    val visionAgentStarted: Boolean,
    val visionAgentError: String?,
    val missingConfiguration: List<String>,
)

class VisionAgentService {
    companion object {
        private const val TAG = "VisionAgentService"
        private val JSON_MEDIA_TYPE = "application/json".toMediaType()
    }

    var onBootstrap: ((VisionAgentBootstrapPayload) -> Unit)? = null
    var onAck: ((Int, Int) -> Unit)? = null
    var onDisconnected: ((String?) -> Unit)? = null
    var onInputTranscription: ((String) -> Unit)? = null
    var onOutputTranscription: ((String) -> Unit)? = null
    var onAudioReceived: ((ByteArray) -> Unit)? = null
    var onTurnComplete: (() -> Unit)? = null

    private val client = OkHttpClient.Builder()
        .readTimeout(0, TimeUnit.MILLISECONDS)
        .pingInterval(10, TimeUnit.SECONDS)
        .build()

    private var webSocket: WebSocket? = null
    private var connectCallback: ((Boolean) -> Unit)? = null
    private var activeSessionId: String? = null

    fun connect(callback: (Boolean) -> Unit) {
        val sessionsUrl = VisionAgentConfig.sessionsUrl()
        if (sessionsUrl == null) {
            Log.e(TAG, "Vision Agent backend sessions URL is not configured")
            callback(false)
            return
        }

        connectCallback = callback
        val payload = JSONObject().apply {
            put("user_id", VisionAgentConfig.userId)
            put("user_name", VisionAgentConfig.userName)
            put("call_type", "default")
            put("start_agent_session", true)
            put("runtime_config", JSONObject().apply {
                put("speech_pipeline", VisionAgentConfig.runtimeConfig.speechPipeline)
                put("enable_pose_processor", VisionAgentConfig.runtimeConfig.enablePoseProcessor)
                put("gemini_llm_model", VisionAgentConfig.runtimeConfig.geminiLlmModel)
                put("fast_whisper_model_size", VisionAgentConfig.runtimeConfig.fastWhisperModelSize)
                put("fast_whisper_device", VisionAgentConfig.runtimeConfig.fastWhisperDevice)
                put("pipeline_turn_delay_ms", VisionAgentConfig.runtimeConfig.pipelineTurnDelayMs)
                put("backend_tts_enabled", VisionAgentConfig.runtimeConfig.backendTtsEnabled)
            })
        }
        val request = Request.Builder()
            .url(sessionsUrl)
            .post(payload.toString().toRequestBody(JSON_MEDIA_TYPE))
            .build()
        Log.d(
            TAG,
            "Bootstrapping Vision Agent session url=$sessionsUrl userId=${VisionAgentConfig.userId} userName=${VisionAgentConfig.userName}",
        )

        client.newCall(request).enqueue(object : okhttp3.Callback {
            override fun onFailure(call: okhttp3.Call, e: IOException) {
                Log.e(TAG, "Session bootstrap failed", e)
                onDisconnected?.invoke(e.message)
                resolveConnect(false)
            }

            override fun onResponse(call: okhttp3.Call, response: Response) {
                response.use {
                    if (!response.isSuccessful) {
                        onDisconnected?.invoke("Bootstrap failed (${response.code})")
                        resolveConnect(false)
                        return
                    }
                    val body = response.body?.string().orEmpty()
                    Log.d(TAG, "Bootstrap response code=${response.code} body=$body")
                    val json = JSONObject(body)
                    val bootstrap = VisionAgentBootstrapPayload(
                        sessionId = json.getString("session_id"),
                        provider = json.optString("provider", "unknown"),
                        callId = json.optString("call_id").ifBlank { null },
                        callType = json.optString("call_type").ifBlank { null },
                        agentSessionId = json.optString("agent_session_id").ifBlank { null },
                        streamApiKey = <REDACTED>"stream_api_key").ifBlank { null },
                        streamUserId = json.optString("stream_user_id").ifBlank { null },
                        streamUserToken = <REDACTED>"stream_user_token").ifBlank { null },
                        visionAgentStarted = json.optBoolean("vision_agent_started", false),
                        visionAgentError = json.optString("vision_agent_error").ifBlank { null },
                        missingConfiguration = buildList {
                            val array = json.optJSONArray("missing_configuration") ?: return@buildList
                            for (index in 0 until array.length()) {
                                add(array.optString(index))
                            }
                        },
                    )
                    Log.d(
                        TAG,
                        "Bootstrap parsed sessionId=${bootstrap.sessionId} provider=${bootstrap.provider} visionAgentStarted=${bootstrap.visionAgentStarted} missing=${bootstrap.missingConfiguration}",
                    )
                    activeSessionId = bootstrap.sessionId
                    onBootstrap?.invoke(bootstrap)
                    openWebSocket(bootstrap.sessionId)
                }
            }
        })
    }

    fun disconnect() {
        Log.d(TAG, "Disconnecting Vision Agent session sessionId=$activeSessionId")
        webSocket?.close(1000, null)
        webSocket = null
        activeSessionId = null
        resolveConnect(false)
    }

    fun sendAudio(data: ByteArray) {
        Log.v(TAG, "Sending audio chunk bytes=${data.size} sessionId=$activeSessionId")
        val json = JSONObject().apply {
            put("realtimeInput", JSONObject().apply {
                put("audio", JSONObject().apply {
                    put("mimeType", "audio/pcm;rate=16000")
                    put("data", Base64.encodeToString(data, Base64.NO_WRAP))
                })
            })
        }
        webSocket?.send(json.toString())
    }

    fun sendVideoFrame(bitmap: Bitmap) {
        val baos = ByteArrayOutputStream()
        bitmap.compress(Bitmap.CompressFormat.JPEG, GeminiConfig.VIDEO_JPEG_QUALITY, baos)
        val imageBytes = baos.toByteArray()
        Log.v(TAG, "Sending video frame bytes=${imageBytes.size} sessionId=$activeSessionId")
        val json = JSONObject().apply {
            put("realtimeInput", JSONObject().apply {
                put("video", JSONObject().apply {
                    put("mimeType", "image/jpeg")
                    put("data", Base64.encodeToString(imageBytes, Base64.NO_WRAP))
                })
            })
        }
        webSocket?.send(json.toString())
    }

    fun sendTextMessage(text: String) {
        Log.d(TAG, "Sending text message sessionId=$activeSessionId text=$text")
        val json = JSONObject().apply {
            put("clientContent", JSONObject().apply {
                put("turns", JSONArray().put(JSONObject().apply {
                    put("role", "user")
                    put("parts", JSONArray().put(JSONObject().apply {
                        put("text", text)
                    }))
                }))
            })
        }
        webSocket?.send(json.toString())
    }

    private fun openWebSocket(sessionId: String) {
        val streamUrl = VisionAgentConfig.streamUrl(sessionId)
        if (streamUrl == null) {
            Log.e(TAG, "Vision Agent backend stream URL is null for sessionId=$sessionId")
            resolveConnect(false)
            return
        }

        Log.d(TAG, "Opening backend websocket url=$streamUrl sessionId=$sessionId")
        val request = Request.Builder().url(streamUrl).build()
        webSocket = client.newWebSocket(request, object : WebSocketListener() {
            override fun onOpen(webSocket: WebSocket, response: Response) {
                Log.d(TAG, "Backend websocket opened for session=$sessionId")
                sendSetupMessage()
            }

            override fun onMessage(webSocket: WebSocket, text: String) {
                handleMessage(text)
            }

            override fun onMessage(webSocket: WebSocket, bytes: ByteString) {
                handleMessage(bytes.utf8())
            }

            override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
                Log.e(TAG, "Backend websocket failure code=${response?.code}", t)
                onDisconnected?.invoke(t.message)
                resolveConnect(false)
            }

            override fun onClosing(webSocket: WebSocket, code: Int, reason: String) {
                Log.w(TAG, "Backend websocket closing session=$sessionId code=$code reason=$reason")
                onDisconnected?.invoke("Connection closed ($code: $reason)")
                resolveConnect(false)
            }
        })
    }

    private fun handleMessage(text: String) {
        try {
            Log.v(TAG, "Backend message: $text")
            val json = JSONObject(text)
            when (json.optString("type")) {
                "session_ready" -> {
                    Log.d(
                        TAG,
                        "session_ready sessionId=${json.optString("session_id")} provider=${json.optString("provider")} bridgeActive=${json.optBoolean("bridge_active")} bridgeError=${json.optString("bridge_error")}",
                    )
                    return
                }

                "ack" -> {
                    val videoFrames = json.optInt("video_frames", 0)
                    val audioChunks = json.optInt("audio_chunks", 0)
                    Log.d(TAG, "ack videoFrames=$videoFrames audioChunks=$audioChunks")
                    onAck?.invoke(videoFrames, audioChunks)
                    return
                }

                "bridge_error" -> {
                    Log.e(TAG, "bridge_error ${json.optString("message", "Realtime bridge error")}")
                    onDisconnected?.invoke(json.optString("message", "Realtime bridge error"))
                    return
                }
            }

            if (json.has("setupComplete")) {
                Log.d(TAG, "setupComplete received sessionId=$activeSessionId")
                resolveConnect(true)
                return
            }

            if (json.has("serverContent")) {
                val serverContent = json.getJSONObject("serverContent")
                if (serverContent.has("inputTranscription")) {
                    val transcriptText =
                        serverContent.getJSONObject("inputTranscription").optString("text", "")
                    if (transcriptText.isNotEmpty()) {
                        Log.d(TAG, "inputTranscription text=$transcriptText")
                        onInputTranscription?.invoke(transcriptText)
                    }
                }
                if (serverContent.has("outputTranscription")) {
                    val transcriptText =
                        serverContent.getJSONObject("outputTranscription").optString("text", "")
                    if (transcriptText.isNotEmpty()) {
                        Log.d(TAG, "outputTranscription text=$transcriptText")
                        onOutputTranscription?.invoke(transcriptText)
                    }
                }
                if (serverContent.optBoolean("turnComplete", false)) {
                    Log.d(TAG, "turnComplete sessionId=$activeSessionId")
                    onTurnComplete?.invoke()
                }
            }

            if (json.has("audioOutput")) {
                val audioOutput = json.getJSONObject("audioOutput")
                val data = audioOutput.optString("data", "")
                if (data.isNotEmpty()) {
                    val decoded = Base64.decode(data, Base64.DEFAULT)
                    Log.d(TAG, "audioOutput bytes=${decoded.size}")
                    onAudioReceived?.invoke(decoded)
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to parse backend message", e)
        }
    }

    private fun sendSetupMessage() {
        Log.d(TAG, "Sending setup message sessionId=$activeSessionId")
        val json = JSONObject().apply {
            put("setup", JSONObject().apply {
                put("model", "backend-adapter")
                put("generationConfig", JSONObject().apply {
                    put("responseModalities", JSONArray().put("AUDIO"))
                })
            })
        }
        webSocket?.send(json.toString())
    }

    private fun resolveConnect(success: Boolean) {
        Log.d(TAG, "resolveConnect success=$success sessionId=$activeSessionId")
        val callback = connectCallback
        connectCallback = null
        callback?.invoke(success)
    }
}

const http = require("http");
const fs = require("fs");
const path = require("path");
const { WebSocketServer } = require("ws");

const PORT = process.env.PORT || 8080;
const rooms = new Map(); // roomCode -> { creator: ws, viewer: ws, destroyTimer: timeout|null }

// Grace period (ms) before destroying a room when creator disconnects.
// Allows the iOS user to switch apps (e.g. copy room code, send via WhatsApp) and come back.
const ROOM_GRACE_PERIOD_MS = 60_000;

// TURN: ExpressTURN (1000 GB/month free, reliable)
// Ports 3478 (standard), 80, 443 (firewall bypass)
const EXPRESSTURN_SERVER = process.env.EXPRESSTURN_SERVER || "free.expressturn.com";
const EXPRESSTURN_USER = process.env.EXPRESSTURN_USER || "efPU52K4SLOQ34W2QY";
const EXPRESSTURN_PASS = process.env.EXPRESSTURN_PASS || "1TJPNFxHKXrZfelz";

function getTurnCredentials() {
  return {
    iceServers: [
      {
        urls: [
          `turn:${EXPRESSTURN_SERVER}:3478`,
          `turn:${EXPRESSTURN_SERVER}:3478?transport=tcp`,
          `turn:${EXPRESSTURN_SERVER}:80`,
          `turn:${EXPRESSTURN_SERVER}:80?transport=tcp`,
          `turns:${EXPRESSTURN_SERVER}:443?transport=tcp`,
        ],
        username: EXPRESSTURN_USER,
        credential: EXPRESSTURN_PASS,
      },
    ],
  };
}

// HTTP server for serving the web viewer
const httpServer = http.createServer((req, res) => {
  // TURN credentials API endpoint
  if (req.url === "/api/turn") {
    const creds = getTurnCredentials();
    res.writeHead(200, {
      "Content-Type": "application/json",
      "Access-Control-Allow-Origin": "*",
    });
    res.end(JSON.stringify(creds));
    return;
  }

  let filePath = path.join(
    __dirname,
    "public",
    req.url === "/" ? "index.html" : req.url
  );

  const ext = path.extname(filePath);
  const contentTypes = {
    ".html": "text/html",
    ".js": "application/javascript",
    ".css": "text/css",
  };

  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("Not found");
      return;
    }
    res.writeHead(200, {
      "Content-Type": contentTypes[ext] || "text/plain",
    });
    res.end(data);
  });
});

// WebSocket signaling server
const wss = new WebSocketServer({ server: httpServer });

function generateRoomCode() {
  // No ambiguous chars (0/O, 1/I/L)
  const chars = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
  let code = "";
  for (let i = 0; i < 6; i++) {
    code += chars[Math.floor(Math.random() * chars.length)];
  }
  return code;
}

wss.on("connection", (ws, req) => {
  let currentRoom = null;
  let role = null; // 'creator' or 'viewer'
  const clientIP = req.headers["x-forwarded-for"] || req.socket.remoteAddress;
  console.log(`[WS] New connection from ${clientIP}`);

  ws.on("message", (data) => {
    let msg;
    try {
      msg = JSON.parse(data);
    } catch {
      return;
    }

    switch (msg.type) {
      case "create": {
        const code = generateRoomCode();
        rooms.set(code, { creator: ws, viewer: null, destroyTimer: null });
        currentRoom = code;
        role = "creator";
        ws.send(JSON.stringify({ type: "room_created", room: code }));
        console.log(`[Room] Created: ${code}`);
        break;
      }

      case "rejoin": {
        // Creator reconnects to an existing room (after app backgrounding)
        const room = rooms.get(msg.room);
        if (!room) {
          ws.send(
            JSON.stringify({ type: "error", message: "Room not found" })
          );
          return;
        }
        // Cancel the destroy timer since creator is back
        if (room.destroyTimer) {
          clearTimeout(room.destroyTimer);
          room.destroyTimer = null;
          console.log(`[Room] Creator rejoined, cancelled destroy timer: ${msg.room}`);
        }
        room.creator = ws;
        currentRoom = msg.room;
        role = "creator";
        ws.send(JSON.stringify({ type: "room_rejoined", room: msg.room }));
        // If viewer is already waiting, trigger a new offer
        if (room.viewer && room.viewer.readyState === 1) {
          ws.send(JSON.stringify({ type: "peer_joined" }));
          console.log(`[Room] Viewer already present, notifying rejoined creator: ${msg.room}`);
        }
        console.log(`[Room] Creator rejoined: ${msg.room}`);
        break;
      }

      case "join": {
        const room = rooms.get(msg.room);
        if (!room) {
          ws.send(
            JSON.stringify({ type: "error", message: "Room not found" })
          );
          return;
        }
        if (room.viewer) {
          ws.send(JSON.stringify({ type: "error", message: "Room is full" }));
          return;
        }
        room.viewer = ws;
        currentRoom = msg.room;
        role = "viewer";
        ws.send(JSON.stringify({ type: "room_joined" }));
        // Notify creator that viewer joined (only if creator is connected)
        if (room.creator && room.creator.readyState === 1) {
          room.creator.send(JSON.stringify({ type: "peer_joined" }));
        }
        console.log(`[Room] Viewer joined: ${msg.room}`);
        break;
      }

      // Relay SDP and ICE candidates to the other peer
      case "offer":
      case "answer":
      case "candidate": {
        const room = rooms.get(currentRoom);
        if (!room) {
          console.log(`[Relay] ${msg.type} from ${role} but room ${currentRoom} not found`);
          return;
        }
        const target = role === "creator" ? room.viewer : room.creator;
        if (target && target.readyState === 1) {
          target.send(JSON.stringify(msg));
          console.log(`[Relay] ${msg.type} from ${role} -> ${role === "creator" ? "viewer" : "creator"} (room ${currentRoom})`);
        } else {
          console.log(`[Relay] ${msg.type} from ${role} but target not ready (room ${currentRoom})`);
        }
        break;
      }
    }
  });

  ws.on("error", (err) => {
    console.log(`[WS] Error for ${role} in room ${currentRoom}: ${err.message}`);
  });

  ws.on("close", (code, reason) => {
    console.log(`[WS] Closed: ${role} in room ${currentRoom} (code=${code}, reason=${reason || "none"})`);

    if (currentRoom && rooms.has(currentRoom)) {
      const room = rooms.get(currentRoom);
      const otherPeer = role === "creator" ? room.viewer : room.creator;
      if (otherPeer && otherPeer.readyState === 1) {
        otherPeer.send(JSON.stringify({ type: "peer_left" }));
      }
      if (role === "creator") {
        // Don't destroy immediately -- give the creator a grace period to reconnect
        // (e.g. switching to WhatsApp to share the room code)
        room.creator = null;
        room.destroyTimer = setTimeout(() => {
          if (rooms.has(currentRoom)) {
            const r = rooms.get(currentRoom);
            // Only destroy if creator never came back
            if (!r.creator || r.creator.readyState !== 1) {
              if (r.viewer && r.viewer.readyState === 1) {
                r.viewer.send(JSON.stringify({ type: "error", message: "Stream ended" }));
              }
              rooms.delete(currentRoom);
              console.log(`[Room] Destroyed after grace period: ${currentRoom}`);
            }
          }
        }, ROOM_GRACE_PERIOD_MS);
        console.log(`[Room] Creator disconnected, grace period started (${ROOM_GRACE_PERIOD_MS / 1000}s): ${currentRoom}`);
      } else {
        room.viewer = null;
      }
    }
  });
});

httpServer.listen(PORT, "0.0.0.0", () => {
  console.log(`Signaling server running on http://0.0.0.0:${PORT}`);
  console.log(`Web viewer available at http://localhost:${PORT}`);
});

