package com.meta.wearable.dat.externalsampleapps.cameraaccess.gemini

import android.annotation.SuppressLint
import android.media.AudioAttributes
import android.media.AudioFormat
import android.media.AudioRecord
import android.media.AudioTrack
import android.media.MediaRecorder
import android.util.Log
import java.io.ByteArrayOutputStream

class AudioManager {
    companion object {
        private const val TAG = "AudioManager"
        private const val MIN_SEND_BYTES = 3200 // 100ms at 16kHz mono Int16 = 1600 frames * 2 bytes
    }

    var onAudioCaptured: ((ByteArray) -> Unit)? = null

    private var audioRecord: AudioRecord? = null
    private var audioTrack: AudioTrack? = null
    private var captureThread: Thread? = null
    @Volatile
    private var isCapturing = false
    private val accumulatedData = ByteArrayOutputStream()
    private val accumulateLock = Any()

    @SuppressLint("MissingPermission")
    fun startCapture() {
        if (isCapturing) return

        val bufferSize = AudioRecord.getMinBufferSize(
            GeminiConfig.INPUT_AUDIO_SAMPLE_RATE,
            AudioFormat.CHANNEL_IN_MONO,
            AudioFormat.ENCODING_PCM_16BIT
        )

        audioRecord = AudioRecord(
            MediaRecorder.AudioSource.VOICE_COMMUNICATION,
            GeminiConfig.INPUT_AUDIO_SAMPLE_RATE,
            AudioFormat.CHANNEL_IN_MONO,
            AudioFormat.ENCODING_PCM_16BIT,
            bufferSize
        )

        audioTrack = AudioTrack.Builder()
            .setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_VOICE_COMMUNICATION)
                    .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                    .build()
            )
            .setAudioFormat(
                AudioFormat.Builder()
                    .setSampleRate(GeminiConfig.OUTPUT_AUDIO_SAMPLE_RATE)
                    .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
                    .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                    .build()
            )
            .setTransferMode(AudioTrack.MODE_STREAM)
            .setBufferSizeInBytes(
                AudioTrack.getMinBufferSize(
                    GeminiConfig.OUTPUT_AUDIO_SAMPLE_RATE,
                    AudioFormat.CHANNEL_OUT_MONO,
                    AudioFormat.ENCODING_PCM_16BIT
                ) * 2
            )
            .build()

        audioRecord?.startRecording()
        audioTrack?.play()
        isCapturing = true

        synchronized(accumulateLock) {
            accumulatedData.reset()
        }

        captureThread = Thread({
            val buffer = ByteArray(bufferSize)
            var tapCount = 0
            while (isCapturing) {
                val read = audioRecord?.read(buffer, 0, buffer.size) ?: break
                if (read > 0) {
                    tapCount++
                    synchronized(accumulateLock) {
                        accumulatedData.write(buffer, 0, read)
                        if (accumulatedData.size() >= MIN_SEND_BYTES) {
                            val chunk = accumulatedData.toByteArray()
                            accumulatedData.reset()
                            if (tapCount <= 3) {
                                Log.d(TAG, "Sending chunk: ${chunk.size} bytes (~${chunk.size / 32}ms)")
                            }
                            onAudioCaptured?.invoke(chunk)
                        }
                    }
                }
            }
        }, "audio-capture").also { it.start() }

        Log.d(TAG, "Audio capture started (16kHz mono PCM16)")
    }

    fun playAudio(data: ByteArray) {
        if (!isCapturing || data.isEmpty()) return
        audioTrack?.write(data, 0, data.size)
    }

    fun stopPlayback() {
        audioTrack?.pause()
        audioTrack?.flush()
        audioTrack?.play()
    }

    fun stopCapture() {
        if (!isCapturing) return
        isCapturing = false

        captureThread?.join(1000)
        captureThread = null

        // Flush remaining accumulated audio
        synchronized(accumulateLock) {
            if (accumulatedData.size() > 0) {
                val chunk = accumulatedData.toByteArray()
                accumulatedData.reset()
                onAudioCaptured?.invoke(chunk)
            }
        }

        audioRecord?.stop()
        audioRecord?.release()
        audioRecord = null

        audioTrack?.stop()
        audioTrack?.release()
        audioTrack = null

        Log.d(TAG, "Audio capture stopped")
    }
}

package com.meta.wearable.dat.externalsampleapps.cameraaccess.openclaw

import android.os.Handler
import android.os.Looper
import android.util.Log
import com.meta.wearable.dat.externalsampleapps.cameraaccess.gemini.GeminiConfig
import java.util.UUID
import java.util.concurrent.TimeUnit
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import org.json.JSONArray
import org.json.JSONObject

class OpenClawEventClient {
    companion object {
        private const val TAG = "OpenClawEventClient"
        private const val MAX_RECONNECT_DELAY_MS = 30_000L
    }

    var onNotification: ((String) -> Unit)? = null

    private var webSocket: WebSocket? = null
    private var isConnected = false
    private var shouldReconnect = false
    private var reconnectDelayMs = 2_000L
    private val handler = Handler(Looper.getMainLooper())

    private val client = OkHttpClient.Builder()
        .readTimeout(0, TimeUnit.MILLISECONDS)
        .pingInterval(10, TimeUnit.SECONDS)
        .build()

    fun connect() {
        if (!GeminiConfig.isOpenClawConfigured) {
            Log.d(TAG, "Not configured, skipping")
            return
        }
        logResolvedConfiguration()
        shouldReconnect = true
        reconnectDelayMs = 2_000L
        establishConnection()
    }

    fun disconnect() {
        shouldReconnect = false
        isConnected = false
        handler.removeCallbacksAndMessages(null)
        webSocket?.close(1000, null)
        webSocket = null
        Log.d(TAG, "Disconnected")
    }

    private fun establishConnection() {
        val url = websocketUrl()

        Log.d(TAG, "Connecting to $url")

        val request = Request.Builder().url(url).build()
        webSocket = client.newWebSocket(request, object : WebSocketListener() {
            override fun onOpen(webSocket: WebSocket, response: Response) {
                Log.d(TAG, "WebSocket opened: HTTP ${response.code} ${response.message}")
            }

            override fun onMessage(webSocket: WebSocket, text: String) {
                handleMessage(text)
            }

            override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
                val responsePreview = response?.body?.string()?.take(300)
                Log.e(
                    TAG,
                    "WebSocket failure: ${t.message}; response=${response?.code} ${response?.message}; body=${responsePreview ?: "<none>"}",
                )
                isConnected = false
                scheduleReconnect()
            }

            override fun onClosing(webSocket: WebSocket, code: Int, reason: String) {
                Log.d(TAG, "WebSocket closing: $code $reason")
                isConnected = false
                scheduleReconnect()
            }
        })
    }

    private fun handleMessage(text: String) {
        try {
            val json = JSONObject(text)
            val type = json.optString("type", "")

            when (type) {
                "event" -> handleEvent(json)
                "res" -> {
                    val ok = json.optBoolean("ok", false)
                    if (ok) {
                        Log.d(TAG, "Connected and authenticated")
                        isConnected = true
                        reconnectDelayMs = 2_000L
                    } else {
                        val error = json.optJSONObject("error")
                        val msg = error?.optString("message", "unknown") ?: "unknown"
                        Log.e(TAG, "Connect failed: $msg")
                    }
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Parse error: ${e.message}")
        }
    }

    private fun handleEvent(json: JSONObject) {
        val event = json.optString("event", "")
        val payload = json.optJSONObject("payload") ?: JSONObject()

        when (event) {
            "connect.challenge" -> sendConnectHandshake()
            "heartbeat" -> handleHeartbeatEvent(payload)
            "cron" -> handleCronEvent(payload)
        }
    }

    private fun sendConnectHandshake() {
        Log.d(
            TAG,
            "Sending OpenClaw handshake: tokenPresent=<REDACTED> tokenLength=<REDACTED>",
        )
        val connectMsg = JSONObject().apply {
            put("type", "req")
            put("id", UUID.randomUUID().toString())
            put("method", "connect")
            put("params", JSONObject().apply {
                put("minProtocol", 1)
                put("maxProtocol", 1)
                put("client", JSONObject().apply {
                    put("id", "gateway-client")
                    put("displayName", "VisionClaw Glass")
                    put("version", "1.0")
                    put("platform", "android")
                    put("mode", "backend")
                })
                put("auth", JSONObject().apply {
                    put("token", GeminiConfig.openClawGatewayToken)
                })
            })
        }
        webSocket?.send(connectMsg.toString())
    }

    private fun handleHeartbeatEvent(payload: JSONObject) {
        val status = payload.optString("status", "")
        if (status != "sent") return

        val preview = payload.optString("preview", "")
        if (preview.isEmpty()) return

        val silent = payload.optBoolean("silent", false)
        if (silent) return

        Log.d(TAG, "Heartbeat notification: ${preview.take(100)}")
        onNotification?.invoke("[Notification from your assistant] $preview")
    }

    private fun handleCronEvent(payload: JSONObject) {
        val action = payload.optString("action", "")
        if (action != "finished") return

        val summary = payload.optString("summary", "").ifEmpty {
            payload.optString("result", "")
        }
        if (summary.isEmpty()) return

        Log.d(TAG, "Cron notification: ${summary.take(100)}")
        onNotification?.invoke("[Scheduled update] $summary")
    }

    private fun scheduleReconnect() {
        if (!shouldReconnect) return
        Log.d(TAG, "Reconnecting in ${reconnectDelayMs}ms")
        handler.postDelayed({
            if (shouldReconnect) {
                reconnectDelayMs = (reconnectDelayMs * 2).coerceAtMost(MAX_RECONNECT_DELAY_MS)
                establishConnection()
            }
        }, reconnectDelayMs)
    }

    private fun websocketUrl(): String {
        val host = GeminiConfig.openClawHost.removeSuffix("/").trim()
        return when {
            host.startsWith("ws://") || host.startsWith("wss://") -> {
                if (Regex(""":\d+$""").containsMatchIn(host)) host else "$host:${GeminiConfig.openClawPort}"
            }
            host.startsWith("https://") -> "wss://${host.removePrefix("https://")}:${GeminiConfig.openClawPort}"
            host.startsWith("http://") -> "ws://${host.removePrefix("http://")}:${GeminiConfig.openClawPort}"
            GeminiConfig.openClawPort == 443 -> "wss://$host:${GeminiConfig.openClawPort}"
            else -> "ws://$host:${GeminiConfig.openClawPort}"
        }
    }

    private fun logResolvedConfiguration() {
        Log.d(
            TAG,
            "Resolved config: host='${GeminiConfig.openClawHost}' normalizedWs='${websocketUrl()}' port=${GeminiConfig.openClawPort} tokenPresent=<REDACTED> tokenLength=<REDACTED>",
        )
    }
}

package com.meta.wearable.dat.externalsampleapps.cameraaccess.webrtc

import android.graphics.Bitmap
import android.util.Log
import org.webrtc.JavaI420Buffer
import org.webrtc.SurfaceTextureHelper
import org.webrtc.VideoCapturer
import org.webrtc.VideoFrame
import org.webrtc.VideoSource
import java.nio.ByteBuffer

/**
 * Custom video capturer that converts Android Bitmaps (from DAT SDK / phone camera)
 * into WebRTC VideoFrames and feeds them to a VideoSource.
 *
 * Replaces iOS CustomVideoCapturer.swift which converts UIImage -> CVPixelBuffer -> RTCVideoFrame.
 */
class CustomVideoCapturer {
    companion object {
        private const val TAG = "CustomVideoCapturer"
    }

    private var videoSource: VideoSource? = null
    private var frameCount: Long = 0

    fun initialize(videoSource: VideoSource) {
        this.videoSource = videoSource
    }

    /**
     * Push a Bitmap frame into the WebRTC video track.
     * Converts ARGB_8888 Bitmap -> I420 YUV -> WebRTC VideoFrame.
     */
    fun pushFrame(bitmap: Bitmap) {
        val source = videoSource ?: return

        val width = bitmap.width
        val height = bitmap.height

        // Extract ARGB pixels
        val argbBuffer = IntArray(width * height)
        bitmap.getPixels(argbBuffer, 0, width, 0, 0, width, height)

        // Allocate I420 buffers
        val ySize = width * height
        val uvSize = (width / 2) * (height / 2)
        val i420Buffer = JavaI420Buffer.allocate(width, height)

        val yBuffer = i420Buffer.dataY
        val uBuffer = i420Buffer.dataU
        val vBuffer = i420Buffer.dataV

        // Convert ARGB -> I420
        var yIndex = 0
        var uvIndex = 0
        for (y in 0 until height) {
            for (x in 0 until width) {
                val pixel = argbBuffer[y * width + x]
                val r = (pixel shr 16) and 0xFF
                val g = (pixel shr 8) and 0xFF
                val b = pixel and 0xFF

                // Y plane
                val yVal = ((66 * r + 129 * g + 25 * b + 128) shr 8) + 16
                yBuffer.put(yIndex++, yVal.coerceIn(0, 255).toByte())

                // U and V planes (subsampled 2x2)
                if (y % 2 == 0 && x % 2 == 0) {
                    val uVal = ((-38 * r - 74 * g + 112 * b + 128) shr 8) + 128
                    val vVal = ((112 * r - 94 * g - 18 * b + 128) shr 8) + 128
                    uBuffer.put(uvIndex, uVal.coerceIn(0, 255).toByte())
                    vBuffer.put(uvIndex, vVal.coerceIn(0, 255).toByte())
                    uvIndex++
                }
            }
        }

        val timestampNs = System.nanoTime()
        val videoFrame = VideoFrame(i420Buffer, 0, timestampNs)
        source.capturerObserver?.onFrameCaptured(videoFrame)
        videoFrame.release()

        frameCount++
        if (frameCount == 1L || frameCount % 120 == 0L) {
            Log.d(TAG, "Pushed frame #$frameCount (${width}x${height})")
        }
    }

    fun dispose() {
        videoSource = null
    }
}

package com.meta.wearable.dat.externalsampleapps.cameraaccess.webrtc

import android.util.Log
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import org.json.JSONObject
import org.webrtc.IceCandidate
import org.webrtc.SessionDescription
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit

sealed class SignalingMessage {
    data class RoomCreated(val room: String) : SignalingMessage()
    data class RoomRejoined(val room: String) : SignalingMessage()
    object RoomJoined : SignalingMessage()
    object PeerJoined : SignalingMessage()
    object PeerLeft : SignalingMessage()
    data class Offer(val sdp: SessionDescription) : SignalingMessage()
    data class Answer(val sdp: SessionDescription) : SignalingMessage()
    data class Candidate(val candidate: IceCandidate) : SignalingMessage()
    data class Error(val message: String) : SignalingMessage()
}

class SignalingClient {
    companion object {
        private const val TAG = "SignalingClient"
    }

    var onMessageReceived: ((SignalingMessage) -> Unit)? = null
    var onConnected: (() -> Unit)? = null
    var onDisconnected: ((String?) -> Unit)? = null

    private var webSocket: WebSocket? = null
    private val sendExecutor = Executors.newSingleThreadExecutor()
    private val client = OkHttpClient.Builder()
        .readTimeout(0, TimeUnit.MILLISECONDS) // No read timeout for WebSocket
        .connectTimeout(30, TimeUnit.SECONDS)
        .build()

    fun connect(url: String) {
        disconnect()

        val request = Request.Builder()
            .url(url)
            .build()

        webSocket = client.newWebSocket(request, object : WebSocketListener() {
            override fun onOpen(webSocket: WebSocket, response: Response) {
                Log.d(TAG, "Connected to $url")
                onConnected?.invoke()
            }

            override fun onMessage(webSocket: WebSocket, text: String) {
                handleMessage(text)
            }

            override fun onClosing(webSocket: WebSocket, code: Int, reason: String) {
                Log.d(TAG, "Closing: $reason")
                webSocket.close(1000, null)
            }

            override fun onClosed(webSocket: WebSocket, code: Int, reason: String) {
                Log.d(TAG, "Closed: $reason")
                onDisconnected?.invoke(reason.ifEmpty { null })
            }

            override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
                Log.e(TAG, "Failure: ${t.message}")
                onDisconnected?.invoke(t.message)
            }
        })
    }

    fun createRoom() {
        sendJSON(JSONObject().put("type", "create"))
    }

    fun joinRoom(code: String) {
        sendJSON(JSONObject().put("type", "join").put("room", code))
    }

    fun rejoinRoom(code: String) {
        sendJSON(JSONObject().put("type", "rejoin").put("room", code))
    }

    fun sendSdp(sdp: SessionDescription) {
        val type = if (sdp.type == SessionDescription.Type.OFFER) "offer" else "answer"
        sendJSON(JSONObject().put("type", type).put("sdp", sdp.description))
    }

    fun sendCandidate(candidate: IceCandidate) {
        sendJSON(
            JSONObject()
                .put("type", "candidate")
                .put("candidate", candidate.sdp)
                .put("sdpMid", candidate.sdpMid ?: "")
                .put("sdpMLineIndex", candidate.sdpMLineIndex)
        )
    }

    fun disconnect() {
        webSocket?.close(1000, "Going away")
        webSocket = null
    }

    private fun sendJSON(json: JSONObject) {
        sendExecutor.execute {
            val ws = webSocket ?: return@execute
            ws.send(json.toString())
        }
    }

    private fun handleMessage(text: String) {
        try {
            val json = JSONObject(text)
            val type = json.optString("type", "")

            when (type) {
                "room_created" -> {
                    val room = json.optString("room", "")
                    if (room.isNotEmpty()) {
                        onMessageReceived?.invoke(SignalingMessage.RoomCreated(room))
                    }
                }
                "room_joined" -> {
                    onMessageReceived?.invoke(SignalingMessage.RoomJoined)
                }
                "room_rejoined" -> {
                    val room = json.optString("room", "")
                    if (room.isNotEmpty()) {
                        onMessageReceived?.invoke(SignalingMessage.RoomRejoined(room))
                    }
                }
                "peer_joined" -> {
                    onMessageReceived?.invoke(SignalingMessage.PeerJoined)
                }
                "peer_left" -> {
                    onMessageReceived?.invoke(SignalingMessage.PeerLeft)
                }
                "offer" -> {
                    val sdp = json.optString("sdp", "")
                    if (sdp.isNotEmpty()) {
                        onMessageReceived?.invoke(
                            SignalingMessage.Offer(
                                SessionDescription(SessionDescription.Type.OFFER, sdp)
                            )
                        )
                    }
                }
                "answer" -> {
                    val sdp = json.optString("sdp", "")
                    if (sdp.isNotEmpty()) {
                        onMessageReceived?.invoke(
                            SignalingMessage.Answer(
                                SessionDescription(SessionDescription.Type.ANSWER, sdp)
                            )
                        )
                    }
                }
                "candidate" -> {
                    val candidate = json.optString("candidate", "")
                    val sdpMid = json.optString("sdpMid", "")
                    val sdpMLineIndex = json.optInt("sdpMLineIndex", 0)
                    if (candidate.isNotEmpty()) {
                        onMessageReceived?.invoke(
                            SignalingMessage.Candidate(
                                IceCandidate(sdpMid, sdpMLineIndex, candidate)
                            )
                        )
                    }
                }
                "error" -> {
                    val msg = json.optString("message", "Unknown signaling error")
                    onMessageReceived?.invoke(SignalingMessage.Error(msg))
                }
                else -> {
                    Log.w(TAG, "Unknown message type: $type")
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to parse signaling message: ${e.message}")
        }
    }
}

